-- stg_mc_package_adjustments: part 1 of 1, 749 rows. NOT APPLIED, branch only.
-- Licence on every row comes from the FILE, never the filename.
create table if not exists public.stg_mc_package_adjustments (
  col text,
  col_2 text,
  package text,
  col_3 text,
  col_4 text,
  item text,
  item_category text,
  col_5 text,
  quantity text,
  reason text,
  note text,
  adj_date text,
  pack_date text,
  user text,
  l_t_e_date text,
  source_file text not null,
  file_sha256 text not null,
  licence text not null,
  file_window text,
  ingested_at timestamptz not null default now()
);
alter table public.stg_mc_package_adjustments enable row level security;
drop policy if exists stg_mc_package_adjustments_read on public.stg_mc_package_adjustments;
create policy stg_mc_package_adjustments_read on public.stg_mc_package_adjustments for select to authenticated using (true);
